import { ElementType } from 'react';
export interface SidebarItem {
    id: string;
    title: string;
    icon: ElementType;
    path: string;
    onPageChange?: () => void;
}
export interface SidebarUtilitiesItem extends SidebarItem {
    target?: '_blank' | '_self';
}
export interface Sidebar {
    items: Array<SidebarItem>;
    utils: Array<SidebarUtilitiesItem>;
}
